// Customer orders API client (deposit pre-orders on the Restock List).
// Generated by fix-customer-requests.ps1 -- it reuses the same request
// helper that api.js already uses for /restock-list, so auth, base URL and
// error handling behave exactly like every other call on this site.
(function () {
  'use strict';
  var STYLE = 'options'; // 'options' -> helper(path, {method, body}) | 'method' -> helper(method, path, body)
  var call = (typeof apiRequest === 'function') ? apiRequest : null;

  function send(method, path, payload) {
    if (!call) {
      throw new Error('Customer orders could not reach the API helper (apiRequest in api.js). Tell Claude: the api.js wiring step failed.');
    }
    if (STYLE === 'method') return call(method, path, payload);
    var opts = { method: method };
    if (payload !== undefined) opts.body = payload;
    return call(path, opts);
  }

  function qs(params) {
    var parts = [];
    Object.keys(params).forEach(function (k) {
      if (params[k] !== undefined && params[k] !== null && params[k] !== '') {
        parts.push(encodeURIComponent(k) + '=' + encodeURIComponent(params[k]));
      }
    });
    return parts.length ? '?' + parts.join('&') : '';
  }

  var BASE = '/restock-list/customer-requests';
  var client = {
    list: function (branchId, status) { return send('GET', BASE + qs({ branch_id: branchId, status: status })); },
    create: function (payload) { return send('POST', BASE, payload); },
    markArrived: function (id, payload) { return send('POST', BASE + '/' + id + '/arrived', payload || {}); },
    update: function (id, payload) { return send('PATCH', BASE + '/' + id, payload || {}); },
    collect: function (id, payload) { return send('POST', BASE + '/' + id + '/collect', payload || {}); },
    cancel: function (id, payload) { return send('POST', BASE + '/' + id + '/cancel', payload || {}); },
    searchProducts: function (q, branchId) { return send('GET', BASE + '/product-search' + qs({ q: q, branch_id: branchId })); }
  };

  if (typeof Api !== 'undefined') { Api.customerRequests = client; }
  window.CustomerRequestsApi = client;
})();
